// Governing: ADR-0007 (Scrape the Full Hunter Roster into a Generated Dataset)
// Implements: SPEC-0003 REQ "List Ordering and Sorting", SPEC-0003 REQ "Hunter Dataset
// Consumption Contract"
//
// The roster seam. `hunters.json` is GENERATED by `node scripts/scrape-hunters.mjs` and
// committed — never hand-edited. Re-running the scrape rewrites it in place.
//
// Landing it was one import, exactly as this file predicted while the roster was still empty.
// Everything downstream — hunter-name ordering, and the picker when it arrives — reads through
// here, so nothing else had to change to pick it up.
//
// `hunterNameFor` still returns null for an unknown id, and that is still the specified
// behaviour rather than a gap: SPEC-0003 requires every consumer to tolerate a `hunterId`
// absent from the dataset, because "the dataset and a user's stored lists refresh
// independently". A hunter retired from the wiki and a hunter never scraped are the same state
// to a consumer, and both resolve to null here.
//
// Each entry carries: id, name, description, portrait, source, acquisition, obtainable,
// sourceRevision, ingestedAt. Portrait assets live at /images/hunters/{portrait}.avif and
// /images/hunters/{portrait}-thumb.avif — derivable from the slug, with no manifest lookup
// (SPEC-0004 REQ "Consumption Contract Compatibility").

// The dataset itself lives at the REPO ROOT (`data/hunters.json`), not beside this file.
// It is a shared artifact: the server reads the same file to validate a favorited hunter
// id, and a copy inside the client workspace was invisible to the server's production
// image. Vite bundles it through this import exactly as it did when it was a sibling.
import hunters from "../../../data/hunters.json";

export const HUNTERS = hunters;

const NAME_BY_ID = new Map(HUNTERS.map((h) => [h.id, h.name]));

/**
 * Resolve a hunter id to its display name, or null when the dataset does not carry it.
 *
 * Null is the ordinary answer, not an error: a list may reference a hunter that has left
 * the roster, or the roster may not be populated at all. SPEC-0003 defines the caller's
 * behaviour in that case (group after everything that resolves; render a placeholder).
 */
export function hunterNameFor(hunterId) {
  if (!hunterId) return null;
  return NAME_BY_ID.get(hunterId) ?? null;
}

const BY_ID = new Map(HUNTERS.map((h) => [h.id, h]));

/** The full dataset entry for an id, or null when the dataset does not carry it. */
export function hunterFor(hunterId) {
  if (!hunterId) return null;
  return BY_ID.get(hunterId) ?? null;
}

// Governing: SPEC-0003 REQ "Hunter Dataset Consumption Contract"
//
// Asset paths are DERIVED from the entry's `portrait` slug, not looked up in a manifest —
// the same property that lets the item scrape add or replace images with no code change
// here (see the note in catalog.js). Both sizes live under the application's own origin;
// nothing in this file, or downstream of it, ever addresses the wiki at runtime.
const PORTRAIT_BASE = "/images/hunters";

/**
 * Ordered portrait URLs for a hunter, best-fit size first.
 *
 * SPEC-0003 requires falling back to the OTHER size before the placeholder: "a too-large
 * image is a performance cost; an empty tile is a defect." So a thumbnail request that
 * 404s retries the full size, and vice versa, and only then does the caller's placeholder
 * take over.
 *
 * Returns an EMPTY array — not a guessed URL — for a hunter absent from the dataset or
 * carrying no `portrait`. That is the difference between "no asset" and "asset missing":
 * with no slug there is no path to derive, so issuing a request would be guessing, and a
 * guaranteed 404 per unknown hunter is a cost with no upside. The caller renders its
 * neutral placeholder immediately instead.
 *
 * @param size "thumb" for picker tiles and list cards, "full" for an expanded header.
 */
export function portraitSources(hunterId, size = "thumb") {
  const portrait = hunterFor(hunterId)?.portrait;
  if (!portrait) return [];
  const full = `${PORTRAIT_BASE}/${portrait}.avif`;
  const thumb = `${PORTRAIT_BASE}/${portrait}-thumb.avif`;
  return size === "full" ? [full, thumb] : [thumb, full];
}

// Governing: SPEC-0003 REQ "The Hunter Picker Is Filterable and Bounded"
//
// Sentinel for the two roster entries whose `acquisition` is null. They are ordinary,
// selectable hunters, so they need a filter bucket of their own — silently dropping them
// from every acquisition filter would make two hunters unreachable by that control.
export const UNKNOWN_ACQUISITION = "__unknown__";

/** Distinct acquisition values present in the dataset, alphabetical, nulls excluded. */
export const ACQUISITIONS = [...new Set(HUNTERS.map((h) => h.acquisition).filter(Boolean))].sort();

/** True when at least one entry has no acquisition — i.e. the Unknown bucket is worth offering. */
export const HAS_UNKNOWN_ACQUISITION = HUNTERS.some((h) => !h.acquisition);

const ACQUISITION_LABELS = { dlc: "DLC" };

/** Display label for an acquisition value: "blood-bonds" -> "Blood bonds", "dlc" -> "DLC". */
export function acquisitionLabel(value) {
  if (!value || value === UNKNOWN_ACQUISITION) return "Unknown";
  if (ACQUISITION_LABELS[value]) return ACQUISITION_LABELS[value];
  const spaced = value.replace(/-/g, " ");
  return spaced.charAt(0).toUpperCase() + spaced.slice(1);
}

// Governing: ADR-0006 (Organize Saved Loadouts into User-Named Lists Illustrated with
// Hunter Portraits), SPEC-0003 REQ "Favorite Hunters"
//
// Section identifiers. The LABELS are the caller's business — "Other hunters" only reads
// correctly when a Favorites section is actually above it — so this seam names the groups
// and leaves the wording to the picker.
export const FAVORITES_SECTION = "favorites";
export const ROSTER_SECTION = "roster";

/** Build the section list, dropping any group with no members. */
function sectionsOf(favoriteMatches, otherMatches) {
  const sections = [];
  // A section with no members is OMITTED rather than emitted empty, so the caller cannot
  // render an empty heading by faithfully mapping over what it was given.
  if (favoriteMatches.length) sections.push({ id: FAVORITES_SECTION, hunters: favoriteMatches });
  if (otherMatches.length) sections.push({ id: ROSTER_SECTION, hunters: otherMatches });
  return { sections, total: favoriteMatches.length + otherMatches.length };
}

/**
 * Narrow the roster to the hunters matching every supplied filter, split into sections.
 *
 * Filtering narrows WHICH hunters are candidates: relative order is the dataset's own, and
 * no hunter is ever treated differently for being referenced by an existing list. That
 * separation is explicit in SPEC-0003 — "The Hunter Picker Is Filterable and Bounded"
 * narrows the candidate set; "The Hunter Picker Does Not Restrict or Mark Reuse" governs
 * how the survivors are presented — so this function is deliberately not given the caller's
 * lists to consult, and cannot consult them.
 *
 * `obtainable` accepts "yes" / "no" / UNKNOWN_ACQUISITION, since the field is nullable for
 * the same two entries. It is 240/242 true and is near-useless alone; the free-text name
 * filter is what actually makes 242 tractable.
 *
 * ---------------------------------------------------------------------------------------
 * Governing: SPEC-0003 REQ "Favorite Hunters" — favorites SECTION AND FILTER, never gate.
 *
 * REVERSAL, 2026-08-10 (#138). This used to return ONE array with favorites sorted to the
 * front. It now returns SECTIONS, because the inline sort was correct about priority and
 * wrong about legibility: in a single 242-tile grid there was no visible boundary between
 * the user's own curation and the alphabet resuming, and the count the user wanted ("I have
 * six favorites") was present in the ordering without being readable anywhere.
 *
 * `favorites` is a Set (or array) of favorited hunter ids. It does two things and neither
 * of them is a gate:
 *
 *   Section.  Favorited matches are lifted into their own group, ahead of the rest, within
 *     whatever filter is already active. The split is applied AFTER narrowing, which is what
 *     makes "no non-matching hunter is shown because it is favorited" true by construction:
 *     a favorite that fails the acquisition filter was dropped before the split ever saw it.
 *     Both groups keep dataset order.
 *
 *   Filter, only if asked.  `favoritesOnly` narrows to favorited hunters, and is the
 *     picker's own toggle rather than anything persisted.
 *
 * A hunter lands in EXACTLY ONE section — never both. Duplicating a favorite into the
 * alphabetical group would preserve completeness at the cost of three things at once: the
 * section counts would stop summing to `total`, the picker's roving tabindex would have to
 * treat one hunter as two focus positions, and favoriting from the lower copy would make a
 * tile appear above while the clicked one stayed put. One hunter, one tile.
 *
 * An EMPTY favorites set behaves as no filter and no split — a single roster section holding
 * everything the other filters left — INCLUDING when `favoritesOnly` is true. That is the
 * spec's "an empty favorites set is not an empty picker": you cannot favorite a hunter you
 * have never seen, so a set that has never been populated must not be able to hide the
 * roster that populates it.
 *
 * @returns {{sections: {id: string, hunters: object[]}[], total: number}} sections in render
 *   order with empty ones omitted, and the total number of hunters across all of them.
 */
export function filterHunters(
  hunters,
  { query = "", acquisition = "", obtainable = "", favorites = null, favoritesOnly = false } = {}
) {
  const q = query.trim().toLowerCase();
  const favored = favorites instanceof Set ? favorites : new Set(favorites || []);
  const matched = hunters.filter((h) => {
    if (q && !h.name.toLowerCase().includes(q)) return false;
    if (acquisition) {
      const matches =
        acquisition === UNKNOWN_ACQUISITION ? !h.acquisition : h.acquisition === acquisition;
      if (!matches) return false;
    }
    if (obtainable) {
      const actual =
        h.obtainable === null || h.obtainable === undefined
          ? UNKNOWN_ACQUISITION
          : h.obtainable
            ? "yes"
            : "no";
      if (actual !== obtainable) return false;
    }
    return true;
  });

  // Nothing favorited: one undivided roster section, so the feature is invisible to a user
  // who has not used it rather than being an empty state they have to escape.
  if (favored.size === 0) return sectionsOf([], matched);

  const isFavorite = (h) => favored.has(h.id);
  const favoriteMatches = matched.filter(isFavorite);
  // With the toggle on there is nothing outside Favorites to show, so the roster section is
  // empty and `sectionsOf` drops it — the same code path as "no unfavorited hunter matched".
  const otherMatches = favoritesOnly ? [] : matched.filter((h) => !isFavorite(h));
  return sectionsOf(favoriteMatches, otherMatches);
}
